import{_ as a,b as t,c as i,g as p}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/12.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/12.md"}'),n={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/12.md"};function o(r,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[p('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 12 章，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来。</p><h2 id="区分-is-a-关系和-part-of-关系。举一个实例-例如-汽车-指出哪些类之间是-is-a-如-电动汽车是汽车-哪些是-part-of-如-发动机是汽车的一部分-。并说明这两种关系在继承上的不同点-属性是否自动传递-。" tabindex="-1">区分 is-a 关系和 part-of 关系。举一个实例（例如“汽车”），指出哪些类之间是 is-a（如 电动汽车是汽车），哪些是 part-of（如 发动机是汽车的一部分）。并说明这两种关系在继承上的不同点（属性是否自动传递）。</h2><h2 id="在分类中-通常用-instance-实例-和-subclass-子类-。给定以下知识" tabindex="-1">在分类中，通常用 instance（实例）和 subclass（子类）。给定以下知识：</h2><p>金毛犬 是 狗 的子类</p><p>狗 是 哺乳动物 的子类</p><p>旺财 是 金毛犬 的实例 请问： (a) 旺财 是否自动是 哺乳动物 的实例？为什么？ (b) 如果 哺乳动物 有属性 恒温，旺财 是否具有该属性？</p><h2 id="解释-默认推理-和-非单调逻辑-。举例说明-从-鸟会飞-和-企鹅是鸟-以及-企鹅不会飞-三个事实中-用默认推理可以得出什么结论-如何用非单调逻辑避免得出矛盾" tabindex="-1">解释“默认推理”和“非单调逻辑”。举例说明：从“鸟会飞”和“企鹅是鸟”以及“企鹅不会飞”三个事实中，用默认推理可以得出什么结论？如何用非单调逻辑避免得出矛盾？</h2><h2 id="设计一个关于-大学-的简单本体-分类和关系-。要求包括" tabindex="-1">设计一个关于“大学”的简单本体（分类和关系）。要求包括：</h2><p>类：人、学生、教师、教授、工作人员、课程</p><p>属性：姓名、年龄、工号/学号</p><p>关系：选课（学生–课程）、授课（教师–课程）、主管（导学关系） 画出类层次图，并标出关键的对象属性和数据属性。</p><h2 id="在描述逻辑中-用-⊓-交-、⊔-并-、∃-存在限定-、∀-值限定-、⊑-包含-等构造子表示以下概念" tabindex="-1">在描述逻辑中，用 ⊓（交）、⊔（并）、∃（存在限定）、∀（值限定）、⊑（包含）等构造子表示以下概念：</h2><p>(a) “母亲” = 女性 并且 至少有一个孩子 (b) “单身父亲” = 男性 并且 有孩子 并且 没有配偶 (c) “甜水果” = 水果 并且 所有糖分都 &gt; 10% (d) “无子女的人” = 人 并且 没有孩子</p><h2 id="继承冲突的处理-考虑-动物-类有属性-运动方式-默认值为-移动-。鱼-是-动物-的子类-但-运动方式-重定义为-游泳-。哺乳动物-也是-动物-的子类-运动方式-重定义为-行走-。现有-鲸-是-哺乳动物-的子类且同时是-鱼-的子类-在通俗概念中-。问-鲸-的-运动方式-应该取什么值-请使用多重继承下的冲突解决方法-如线性化、显式声明、优先深度等-并讨论优缺点。" tabindex="-1">继承冲突的处理：考虑 动物 类有属性 运动方式，默认值为“移动”。鱼 是 动物 的子类，但 运动方式 重定义为“游泳”。哺乳动物 也是 动物 的子类，运动方式 重定义为“行走”。现有 鲸 是 哺乳动物 的子类且同时是 鱼 的子类（在通俗概念中）。问：鲸 的 运动方式 应该取什么值？请使用多重继承下的冲突解决方法（如线性化、显式声明、优先深度等），并讨论优缺点。</h2><h2 id="设计一个简单的事件演算-event-calculus-表示" tabindex="-1">设计一个简单的事件演算（Event Calculus）表示：</h2><p>动作 开门 导致状态 门开</p><p>动作 关门 导致 门关</p><p>初始状态 门关</p><p>发生在时间点 1 的动作 开门 用事件演算谓词（如 Happens(e,t), Initiates(e,f,t), Terminates(e,f,t), HoldsAt(f,t)）推导出 HoldsAt(门开, 2) 成立。写出推理步骤。</p><h2 id="描述逻辑推理-给定以下术语" tabindex="-1">描述逻辑推理：给定以下术语：</h2><p>Mother ≡ Woman ⊓ ∃hasChild.Person</p><p>Parent ≡ Person ⊓ ∃hasChild.Person</p><p>Grandmother ≡ Mother ⊓ ∃hasChild.Parent</p><p>Woman ⊑ Person 判断 Grandmother ⊑ Mother 是否成立？并解释包含关系如何推导。（提示：用描述逻辑的包含推理规则）</p><h2 id="本体评估与调试-假设你构建了一个医疗诊断本体-包含类-疾病、症状、药物。你发现推理机无法得出-病人有发烧症状时可能感染病毒-这一结论。请分析可能的原因-如缺失属性限制、范围不足、公理不足-并提出三种增强本体的方案。" tabindex="-1">本体评估与调试：假设你构建了一个医疗诊断本体，包含类 疾病、症状、药物。你发现推理机无法得出“病人有发烧症状时可能感染病毒”这一结论。请分析可能的原因（如缺失属性限制、范围不足、公理不足），并提出三种增强本体的方案。</h2><h2 id="语义网应用-设计一个简单的图书推荐系统-利用rdf-owl表示用户偏好和书籍元数据。具体要求" tabindex="-1">语义网应用：设计一个简单的图书推荐系统，利用RDF/OWL表示用户偏好和书籍元数据。具体要求：</h2><p>书籍有类别（如科幻、历史、技术）、作者、评分。</p><p>用户有已读列表、喜欢类别、评分阈值。</p><p>定义推理规则：如果用户喜欢某类别且书籍评分&gt;用户阈值，则推荐。 写出必要的OWL类、属性、个体实例及SWRL规则（或简单逻辑规则）。说明推理机如何产生推荐结果。</p><h2 id="比较逻辑表示与深度学习表示" tabindex="-1">比较逻辑表示与深度学习表示：</h2><p>知识表示（如描述逻辑、本体）与深度学习的嵌入表示（如Word2Vec、知识图谱嵌入）在表达能力和推理方式上有何不同？请各列出两点优势与劣势，并举例说明在哪个场景下传统知识表示更优，哪个场景下深度学习更优。</p>',31)])])}const m=a(n,[["render",o]]);export{_ as __pageData,m as default};
